function reviveValue(value) {
  if (value && typeof value === 'object' && value.__date) {
    return new Date(value.__date);
  }
  return value;
}

function applySheetSettings(ws, data) {
  ws.properties.showGridLines = data.gridLines;
  ws.views = [{
    state: 'normal',
    zoomScale: data.zoom || 100,
    activeCell: data.active || undefined
  }];

  for (const [col, width] of Object.entries(data.widths || {})) {
    ws.getColumn(col).width = width;
  }
  for (const [row, height] of Object.entries(data.heights || {})) {
    ws.getRow(Number(row)).height = height;
  }
  for (const row of data.hiddenRows || []) ws.getRow(row).hidden = true;
  for (const col of data.hiddenCols || []) ws.getColumn(col).hidden = true;

  for (const range of data.merges || []) ws.mergeCells(range);

  const ps = data.pageSetup || {};
  ws.pageSetup = {
    orientation: ps.orientation || 'landscape',
    paperSize: ps.paperSize || undefined,
    fitToWidth: ps.fitToWidth == null ? undefined : ps.fitToWidth,
    fitToHeight: ps.fitToHeight == null ? undefined : ps.fitToHeight,
    scale: ps.scale == null ? undefined : ps.scale,
    fitToPage: true,
    margins: data.pageMargins || undefined
  };

  if (data.printArea) {
    const m = data.printArea.match(/!\$?([A-Z]+\$?\d+):\$?([A-Z]+\$?\d+)/);
    ws.pageSetup.printArea = m
      ? `${m[1].replaceAll('$','')}:${m[2].replaceAll('$','')}`
      : data.printArea.replaceAll('$','');
  }
  if (data.printTitlesRows) {
    ws.pageSetup.printTitlesRow = data.printTitlesRows.replaceAll('$','');
  }
  if (data.printTitlesCols) {
    ws.pageSetup.printTitlesColumn = data.printTitlesCols.replaceAll('$','');
  }
}

async function createWorkbook() {
  const workbook = new ExcelJS.Workbook();
  workbook.creator = 'ExcelJS converter';
  workbook.lastModifiedBy = 'ExcelJS converter';

  if (workbook.calcProperties) {
    workbook.calcProperties.calcMode = 'auto';
    workbook.calcProperties.fullCalcOnLoad = true;
    workbook.calcProperties.forceFullCalc = true;
  }

//   const imageIds = {};
//   for (const [key, image] of Object.entries(IMAGES)) {
//     imageIds[key] = workbook.addImage({
//       base64: `data:image/png;base64,${image.data}`,
//       extension: 'png'
//     });
//   }

  for (const data of SHEETS) {
    const ws = workbook.addWorksheet(data.name);
    applySheetSettings(ws, data);

    for (const item of data.cells) {
        const cell = ws.getCell(item.addr);
        if (item.formula !== undefined) {
            const result = reviveValue(item.result);
            console.log("-- RESULTTTTTTTTTTTTTTTTTTTTT --------")
            console.log(result)
            cell.value = result === null || result === undefined
            ? { formula: item.formula }
            : { formula: item.formula, result };
        } else if (item.value !== null && item.value !== undefined) {
            cell.value = reviveValue(item.value);
        }

        if (STYLES[item.style]) cell.style = STYLES[item.style];
    }

    // for (const img of data.images || []) {
    //   const id = imageIds[img.key];
    //   if (id === undefined) continue;
    //   ws.addImage(id, {
    //     tl: { col: img.col, row: img.row },
    //     ext: { width: img.width, height: img.height },
    //     editAs: 'oneCell'
    //   });
    // }
  }

  await workbook.xlsx.writeFile(OUTPUT_FILE);
  console.log(`Created: ${OUTPUT_FILE}`);
  console.log(`Sheets: ${workbook.worksheets.length}`);
}

module.exports = {
    createWorkbook
};